insert into public.faqs (slug, category, question, answer_md, sort_order) values
  ('delivery', 'general', 'How long does delivery take?', 'Servers are delivered after we verify your payment. The typical time is shown on your order page, and we notify you by email and in your dashboard as soon as your server is ready.', 1),
  ('os', 'general', 'What operating system do you provide?', 'Every server runs Windows. We currently offer a single Windows Server image on all plans.', 2),
  ('term', 'general', 'How does the 30-day term work?', 'A plan runs for 30 days from delivery. Renew from your dashboard before it expires to add another 30 days.', 3),
  ('payments', 'general', 'Which payment methods do you accept?', 'We accept manual payments such as bank transfer, mobile wallets, UPI and crypto, depending on your region. Choose a method at checkout, send the payment, and upload proof.', 4),
  ('refunds', 'general', 'Can I get a refund?', 'Refund eligibility is described in our Refund Policy. Refunds are handled manually by our team.', 5),
  ('location', 'general', 'Can I change my server''s location later?', 'Locations are fixed per server. To move, order a new server in the location you need.', 6),
  ('connect', 'general', 'How do I connect to my server?', 'Use Remote Desktop Connection on Windows, Windows App on macOS, or the Remote Desktop app on Android and iOS, with the IP address, port, username and password shown in your dashboard.', 7),
  ('abuse', 'general', 'What is not allowed?', 'Spam, DDoS, fraud, malware and other abuse prohibited by our Acceptable Use Policy lead to suspension without refund.', 8)
on conflict (slug) do nothing;
